// Block (composition) — a responsive comparison of product plans.
// Existing Badge and Button variants communicate the featured plan without new look.
import type { Ref } from "react";
import { Badge } from "../components/Badge";
import { Button } from "../components/Button";
import { Card } from "../components/Card";
import { Grid } from "../layouts/Grid";
import { Stack } from "../layouts/Stack";
import "./PricingTable.css";

export interface PricingTableProps {
  /** Plans to compare. */
  plans: {
    name: string;
    price: string;
    period?: string;
    features: string[];
    ctaLabel?: string;
    featured?: boolean;
  }[];
  /** Called with the selected plan name. */
  onSelect?: (name: string) => void;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function PricingTable({ plans, onSelect, className, ref }: PricingTableProps) {
  const desktopColumns = Math.min(Math.max(plans.length, 1), 4);

  return (
    <Grid
      as="section"
      ref={ref}
      columns={{ small: 1, medium: desktopColumns }}
      gap="medium"
      aria-label="Pricing plans"
      className={className ? `sd-pricingtable ${className}` : "sd-pricingtable"}
    >
      {plans.map((plan) => (
        <Card key={plan.name}>
          <Stack gap="small" className="sd-pricingtable__content">
            {/* The plan name and its price are ONE unit, at a tighter rung than the card's
                own, the pair `ProductCard` already groups. Flat, the same 8px separated the
                name from its price as separated that price from the feature list below it. */}
            <Stack gap="2x-small" className="sd-pricingtable__header">
              <Stack direction="row" align="center" gap="x-small" className="sd-pricingtable__heading">
                <>
                  <h3 className="sd-pricingtable__name sd-type-title-medium">{plan.name}</h3>
                </>
                {plan.featured && <Badge variant="tonal">Popular</Badge>}
              </Stack>
              <>
                <p className="sd-pricingtable__price sd-type-headline-medium">
                  {plan.price}
                  {plan.period && (
                    <small className="sd-pricingtable__period sd-type-caption-medium">
                      {plan.period}
                    </small>
                  )}
                </p>
              </>
            </Stack>
            <ul className="sd-pricingtable__features sd-type-body-medium">
              {plan.features.map((feature) => (
                <li key={feature}>{feature}</li>
              ))}
            </ul>
            <Button
              variant={plan.featured ? "primary" : "secondary"}
              onPress={() => onSelect?.(plan.name)}
            >
              {plan.ctaLabel ?? `Choose ${plan.name}`}
            </Button>
          </Stack>
        </Card>
      ))}
    </Grid>
  );
}

/* PricingTable.css — .sd-pricingtable (Block)
   Arrangement only: full-width grid and native text/list spacing normalization. */
.sd-pricingtable {
  width: 100%;
}

.sd-pricingtable__name,
.sd-pricingtable__price,
.sd-pricingtable__features {
  margin: 0;
}

.sd-pricingtable__period {
  margin-inline-start: var(--sd-space-2x-small);
}

.sd-pricingtable__features {
  padding-inline-start: var(--sd-space-large);
}
